# Memo family: all store.* references containing "Memo" + associated types (Visibility, Public, Protected, Private)
{
  grep -rn 'store\.[A-Za-z]*Memo[A-Za-z]*' /bench/repo --include='*.go'
  grep -rn 'store\.Visibility[A-Za-z]*\|store\.Public[^A-Za-z]\|store\.Protected[^A-Za-z]\|store\.Private[^A-Za-z]' /bench/repo --include='*.go'
  grep -rn 'store\.ListMemos[^A-Za-z]' /bench/repo --include='*.go'
} | grep -v '/bench/repo/store/' | grep -v '/bench/repo/proto/gen/store/' | sed 's|/[^/]*\.go:.*||' | sort -u

# User family: all store.* references containing "User" + associated types (Role*, RowStatus)
{
  grep -rn 'store\.[A-Za-z]*User[A-Za-z]*' /bench/repo --include='*.go'
  grep -rn 'store\.Role[A-Za-z]*' /bench/repo --include='*.go'
  grep -rn 'store\.ListUsers[^A-Za-z]' /bench/repo --include='*.go'
} | grep -v '/bench/repo/store/' | grep -v '/bench/repo/proto/gen/store/' | sed 's|/[^/]*\.go:.*||' | sort -u

# Check inbox with the UNREAD/ARCHIVED constants included
{
  grep -rn 'store\.[A-Za-z]*Inbox[A-Za-z]*' /bench/repo --include='*.go'
  grep -rn 'store\.UNREAD[^A-Za-z]\|store\.ARCHIVED[^A-Za-z]\|store\.InboxStatus[^A-Za-z]\|store\.InboxMessage[^A-Za-z]' /bench/repo --include='*.go'
} | grep -v '/bench/repo/store/' | grep -v '/bench/repo/proto/gen/store/' | sed 's|/[^/]*\.go:.*||' | sort -u

# Double check - get exact count for Memo family
{
  grep -rn 'store\.[A-Za-z]*Memo[A-Za-z]*' /bench/repo --include='*.go'
  grep -rn 'store\.Visibility[A-Za-z]*\|store\.Public[^A-Za-z]\|store\.Protected[^A-Za-z]\|store\.Private[^A-Za-z]' /bench/repo --include='*.go'
} | grep -v '/bench/repo/store/' | grep -v '/bench/repo/proto/gen/store/' | sed 's|/[^/]*\.go:.*||' | sort -u | wc -l

# Double check - get exact count for User family
{
  grep -rn 'store\.[A-Za-z]*User[A-Za-z]*' /bench/repo --include='*.go'
  grep -rn 'store\.Role[A-Za-z]*' /bench/repo --include='*.go'
  grep -rn 'store\.PAT[A-Za-z]*\|store\.RefreshToken[A-Za-z]*' /bench/repo --include='*.go'
} | grep -v '/bench/repo/store/' | grep -v '/bench/repo/proto/gen/store/' | sed 's|/[^/]*\.go:.*||' | sort -u | wc -l

# Memo family complete list including ListMemos
{
  grep -rn 'store\.[A-Za-z]*Memo[A-Za-z]*' /bench/repo --include='*.go'
  grep -rn 'store\.Visibility[A-Za-z]*\|store\.Public[^A-Za-z]\|store\.Protected[^A-Za-z]\|store\.Private[^A-Za-z]' /bench/repo --include='*.go'
  grep -rn 'store\.ListMemos[^A-Za-z]' /bench/repo --include='*.go'
} | grep -v '/bench/repo/store/' | grep -v '/bench/repo/proto/gen/store/' | sed 's|/[^/]*\.go:.*||' | sort -u
